BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial threshold application
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakewood Electronics, the engagement team identifies a $175 misclassification between office supplies and postage expense. Performance materiality for the engagement is $120,000. Under AU-C 450, the auditor''s most appropriate action is to:', '["Not accumulate it because amounts clearly trivial to the financial statements need not be tracked", "Accumulate it on the summary because all identified misstatements require documentation regardless of size", "Project the misclassification to the full expense population and include the projected amount", "Report it to those charged with governance as a potential significant deficiency"]'::jsonb, 0, 'Under AU-C 450.05, the auditor accumulates misstatements identified during the audit other than those that are clearly trivial. Clearly trivial describes amounts well below materiality where accumulation is unnecessary. A $175 item against $120,000 performance materiality qualifies as clearly trivial. Unlike merely immaterial misstatements, clearly trivial items need not be accumulated at all.', 'medium', 2),

-- Q2: medium / L3 — Iron curtain vs rollover approach to evaluating misstatements
(1, 'Misstatements and Control Deficiencies', 'Greenfield Corporation has carried forward $40,000 in uncorrected misstatements from prior periods. Current-year income is $2 million, and financial statement materiality is $100,000. The auditor is evaluating whether the cumulative balance sheet effect warrants a report modification. This evaluation approach is best described as the:', '["Rollover method, which focuses on current-year income statement impact only", "Iron curtain method, which considers the cumulative balance sheet effect of uncorrected misstatements", "Projected misstatement method, which extrapolates sample errors to the full population", "Dual approach, which weights income statement and balance sheet materiality equally"]'::jsonb, 1, 'Under AU-C 450.A16, the iron curtain approach evaluates uncorrected misstatements based on their cumulative effect on the current-period balance sheet, regardless of when they originated. This contrasts with the rollover approach, which focuses only on the current-year impact on the income statement. Auditors typically consider both methods when evaluating aggregate misstatements to form their overall opinion.', 'medium', 3),

-- Q3: easy / L1 — Definition of clearly trivial
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what distinguishes a ''clearly trivial'' misstatement from one that is merely immaterial?', '["Clearly trivial misstatements must still be accumulated on the misstatement summary", "Clearly trivial refers only to misstatements caused by rounding differences", "Clearly trivial amounts are well below materiality and could not affect users'' decisions individually or in aggregate", "Clearly trivial and immaterial are interchangeable terms under auditing standards"]'::jsonb, 2, 'AU-C 450.A2 states that clearly trivial is not another expression for not material. Clearly trivial describes misstatements of a wholly different and smaller order of magnitude than materiality, where accumulation is unnecessary. An immaterial misstatement may still need accumulation because its combination with others could become material. The two terms represent distinctly different thresholds.', 'easy', 1),

-- Q4: easy / L1 — Control deficiencies not requiring written communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which type of internal control deficiency does not require written communication to those charged with governance?', '["A material weakness identified during the current-year audit", "A significant deficiency identified during the prior year that remains unremediated", "A significant deficiency identified during the current-year audit", "A control deficiency that the auditor judges to be neither a significant deficiency nor a material weakness"]'::jsonb, 3, 'AU-C 265.11 requires written communication of significant deficiencies and material weaknesses to those charged with governance. Lesser deficiencies — those not rising to significant deficiency or material weakness level — are not required to be communicated in writing, though the auditor may choose to do so. Unlike significant deficiencies, lesser control deficiencies have no mandatory written communication requirement.', 'easy', 1),

-- Q5: hard / L4 — Multi-factor qualitative and quantitative evaluation
(1, 'Misstatements and Control Deficiencies', 'Pacific Northwest Bank has a $45,000 uncorrected misstatement in loan loss reserves, below the $200,000 materiality threshold. However, the misstatement moves the bank''s capital adequacy ratio below the regulatory minimum, changes a reported loss to reported income, and affects a ratio in the CEO''s bonus covenant. The auditor should conclude that:', '["The misstatement is material due to qualitative factors despite being quantitatively immaterial", "The misstatement is immaterial because it falls below the established materiality threshold", "The misstatement requires only footnote disclosure rather than correction", "The misstatement should be accumulated with other items and evaluated in aggregate only"]'::jsonb, 0, 'AU-C 450.11 requires evaluating uncorrected misstatements considering both quantitative and qualitative factors. Per AU-C 450.A20, qualitative factors include effects on regulatory compliance, debt covenants, and trend reversals. All three qualitative factors here indicate the misstatement is material to users'' decisions. Quantitative immateriality alone does not override significant qualitative considerations that affect the overall fair presentation.', 'hard', 4),

-- Q6: hard / L4 — PCAOB strong indicators of material weakness
(1, 'Misstatements and Control Deficiencies', 'During the integrated audit of Meridian Industries, the auditor discovers that the CFO overstated revenue by $50,000 in a quarter where the company narrowly met analyst earnings estimates. Financial statement materiality is $500,000. Under PCAOB AS 2201, the auditor should evaluate this as a potential material weakness primarily because:', '["Any misstatement below materiality is automatically a significant deficiency in an integrated audit", "Fraud by senior management is only classified as a material weakness when it exceeds materiality", "The auditor should first assess whether compensating controls mitigated the risk before classifying severity", "Identification of fraud by senior management is a strong indicator of material weakness regardless of amount"]'::jsonb, 3, 'PCAOB AS 2201.69 identifies several strong indicators of material weakness, including identification of fraud by senior management, whether or not material. Fraud by those responsible for designing and maintaining controls undermines the entire control environment. Unlike inadvertent errors, intentional override by senior management signals a systemic failure that compensating controls cannot reliably mitigate, warranting material weakness classification.', 'hard', 4),

-- Q7: easy / L1 — Recipients of written communication of deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom must the auditor provide written communication of significant deficiencies and material weaknesses?', '["Management only, who then decides whether to inform the board of directors", "Those charged with governance and management", "The external regulatory authority overseeing the entity", "The audit committee only, excluding operational management"]'::jsonb, 1, 'AU-C 265.11-12 requires the auditor to communicate significant deficiencies and material weaknesses in writing to both those charged with governance and management. Governance needs awareness for oversight responsibilities, while management needs the information to take corrective action. Unlike lesser deficiencies, significant deficiencies and material weaknesses must be communicated to both parties.', 'easy', 1),

-- Q8: medium / L2 — Prior-period uncorrected misstatements reversal impact
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Manufacturing, the auditor notes that a $30,000 prior-year overstatement of prepaid insurance has reversed into the current year, reducing current-year insurance expense. Materiality is $150,000. Under AU-C 450, the auditor should:', '["Ignore the reversal because the misstatement was evaluated and accepted in the prior-year audit", "Treat the $30,000 as a newly identified current-year misstatement requiring separate evaluation", "Consider the effect of the prior-period reversal when evaluating current-year aggregate misstatements", "Require management to restate the prior-year financial statements before continuing the current audit"]'::jsonb, 2, 'AU-C 450.06 requires the auditor to determine whether the overall audit strategy needs revision by evaluating the effect of uncorrected prior-period misstatements on current-period financial statements. A prior-year overstatement that reverses reduces current-year expenses, affecting the income statement. Ignoring the reversal would misstate the aggregate evaluation, but it does not require prior-year restatement.', 'medium', 2),

-- Q9: hard / L4 — IT general control deficiency pervasiveness evaluation
(1, 'Misstatements and Control Deficiencies', 'Silverlake Financial''s IT department lacks a formal change management process for its general ledger application. During the year, three unauthorized program changes were deployed that altered journal entry posting logic. No financial misstatements were detected through substantive testing. Under AU-C 265, the auditor should evaluate this deficiency considering:', '["Only the actual misstatements detected, concluding it is a lesser deficiency since no errors were found", "The dollar amount of transactions processed by the general ledger system during the period only", "Whether the change management deficiency affects only IT operations rather than financial reporting", "The pervasive nature of the IT control failure and its potential to affect multiple financial statement assertions"]'::jsonb, 3, 'AU-C 265.A12 indicates severity assessment considers the magnitude of potential misstatements and likelihood of occurrence. An IT general control weakness affecting general ledger change management is pervasive because it undermines reliance on all application controls. The absence of detected misstatements does not reduce severity — the deficiency''s potential impact on multiple assertions drives classification, not actual errors found.', 'hard', 4),

-- Q10: medium / L3 — Systematic misstatements requiring population-level projection
(1, 'Misstatements and Control Deficiencies', 'While auditing Bridgeport Distributors, the auditor discovers that all 12 sampled intercompany elimination entries contain identical $50 rounding errors, totaling $600 in the sample. The errors result from a flawed spreadsheet formula used for all 200 elimination entries. The auditor should:', '["Recognize this as a systematic error and project the misstatement to all 200 elimination entries", "Evaluate only the $600 found in the sample because projection applies solely to random sampling errors", "Classify the $600 as clearly trivial because individual errors are only $50 each", "Request management correct the 12 sampled items and accept the remaining entries as properly stated"]'::jsonb, 0, 'Under AU-C 450.05-.06, when the auditor identifies a systematic misstatement caused by a flawed process, the known error should be projected to the full population. A formulaic spreadsheet error affecting all 200 entries is systematic, not random. Projecting only the sampled amount would understate the likely misstatement. Unlike random errors, systematic errors require evaluation of the entire affected population.', 'medium', 3),

-- Q11: medium / L2 — Management representation letter regarding uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Timber Ridge Construction, the auditor has accumulated $35,000 in uncorrected misstatements that management has declined to correct. Before issuing the audit report, the auditor should obtain from management under AU-C 580:', '["A verbal acknowledgment that the uncorrected misstatements exist but are not material", "A separate engagement letter specifically addressing the uncorrected misstatements identified", "Written authorization to disclose the uncorrected misstatements in the auditor''s report", "A written representation that the effects of uncorrected misstatements are immaterial individually and in aggregate"]'::jsonb, 3, 'AU-C 580.16 requires the auditor to request a written representation from management that the effects of uncorrected misstatements aggregated during the audit are immaterial, both individually and in aggregate, to the financial statements as a whole. The summary of uncorrected items must be attached. A verbal acknowledgment is insufficient — AU-C 580 specifically requires the representation in writing.', 'medium', 2),

-- Q12: easy / L1 — Definition of pervasive in the context of misstatements
(1, 'Misstatements and Control Deficiencies', 'In auditing standards, what does ''pervasive'' mean when describing the effect of misstatements on financial statements?', '["The misstatements affect multiple elements, accounts, or disclosures and are not confined to specific items", "The misstatements exceed overall materiality for the financial statements as a whole", "The misstatements were caused by fraud rather than by unintentional error", "The misstatements require restatement of prior-period financial statements"]'::jsonb, 0, 'Under AU-C 705.06, pervasive describes effects not confined to specific elements, accounts, or items but instead affecting multiple areas of the financial statements, or representing a substantial proportion of the statements. Pervasiveness relates to how widespread the impact is, not solely to dollar magnitude. A misstatement can exceed materiality without being pervasive if it affects only one isolated account.', 'easy', 1),

-- Q13: medium / L2 — Timing of written communication of deficiencies
(1, 'Misstatements and Control Deficiencies', 'Archer & Associates completes the December 31, 2025, audit of Summit Logistics and issues the audit report on March 15, 2026. The engagement team identified two significant deficiencies during fieldwork. Under AU-C 265, the written communication should be issued no later than:', '["December 31, 2025, the date of the financial statements under audit", "60 days following the audit report release date", "March 15, 2026, the date the audit report is issued", "The start of the next fiscal year''s audit engagement"]'::jsonb, 1, 'AU-C 265.13 requires the auditor to communicate significant deficiencies and material weaknesses in writing no later than 60 days following the report release date. The communication need not coincide with the report date itself. Setting the deadline at report issuance is too early, as the auditor may still be finalizing the evaluation, while waiting until the next engagement would deprive governance of timely information.', 'medium', 2),

-- Q14: medium / L3 — Qualitative factors affecting misstatement materiality
(1, 'Misstatements and Control Deficiencies', 'Redwood Healthcare has a $22,000 understatement of charity care expense against $500,000 materiality. The understatement causes the hospital''s reported charity care percentage to fall below the 5% threshold required to maintain its tax-exempt status. Under AU-C 450, the auditor should:', '["Treat the misstatement as immaterial because it is less than 5% of materiality", "Accumulate it without special consideration since it does not exceed materiality", "Evaluate the qualitative significance because the misstatement affects compliance with the tax-exempt threshold", "Require management to reclassify the amount as a contingent liability disclosure"]'::jsonb, 2, 'AU-C 450.A20 identifies qualitative factors that may cause a quantitatively immaterial misstatement to be material, including effects on regulatory compliance and contractual provisions. A misstatement causing an entity to fail a tax-exempt threshold has significance beyond its dollar amount. Simply accumulating the misstatement without considering its qualitative regulatory impact would be insufficient under the standard.', 'medium', 3),

-- Q15: hard / L3 — Nature of corrected misstatements informing audit strategy
(1, 'Misstatements and Control Deficiencies', 'During the audit of Atlas Aerospace, the auditor identifies 15 revenue recognition misstatements totaling $180,000, all of which management promptly corrects. Overall materiality is $250,000. Although no uncorrected misstatements remain, the auditor concludes additional procedures are warranted. The most likely reason is:', '["Corrected misstatements must be projected to estimate undetected errors in untested transactions", "The auditor must report all corrected misstatements as significant deficiencies to governance", "Management''s willingness to correct the misstatements indicates they were fraudulent in nature", "The volume and pattern of corrected misstatements may indicate a higher risk of additional undetected misstatement"]'::jsonb, 3, 'AU-C 450.08 requires the auditor to consider whether the nature and circumstances of identified misstatements — even corrected ones — indicate that other undetected misstatements may exist that, combined with uncorrected items, could be material. Fifteen revenue errors suggest a systematic process weakness. Corrected misstatements do not automatically become significant deficiencies, but their pattern informs risk assessment and may require expanding procedures.', 'hard', 3),

-- Q16: medium / L2 — Auditor must request correction of all accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'Pine Valley Industries has three uncorrected misstatements totaling $42,000 against materiality of $200,000. The CFO argues that correction is unnecessary since the aggregate is well below materiality. Under AU-C 450, the auditor should:', '["Request that management correct all accumulated misstatements regardless of their relationship to materiality", "Accept management''s position because the aggregate amount is clearly below materiality", "Issue a qualified opinion to disclose management''s refusal to correct identified errors", "Increase the materiality threshold to accommodate the uncorrected items"]'::jsonb, 0, 'AU-C 450.07 requires the auditor to communicate all accumulated misstatements to the appropriate level of management and request correction, regardless of whether the aggregate is below materiality. The standard does not condition this request on magnitude. Management may decline, but the auditor must make the request. Accepting without requesting correction conflicts with the auditor''s responsibility under AU-C 450.', 'medium', 2),

-- Q17: medium / L2 — Design deficiency vs operating deficiency
(1, 'Misstatements and Control Deficiencies', 'Cedar Point Manufacturing has a written policy requiring dual authorization for journal entries exceeding $10,000. During testing, the auditor finds the general ledger system allows single-user posting without enforcing the dual-authorization requirement. Under AU-C 265, this is best classified as:', '["An operating deficiency because employees are not following the established policy", "A design deficiency because the control is not properly designed to prevent or detect misstatements", "A compensating control failure because the system should supplement the manual control", "An IT general control weakness unrelated to internal control over financial reporting"]'::jsonb, 1, 'Under AU-C 265.A1, a design deficiency exists when a control necessary to meet a control objective is missing or not properly designed such that even if it operates as designed, it would not prevent or detect misstatements on a timely basis. The system failing to enforce dual authorization is a design flaw. An operating deficiency occurs when a properly designed control does not operate effectively due to human error or circumvention.', 'medium', 2),

-- Q18: medium / L2 — Known vs likely (projected) misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Heritage Foods, the auditor tests a sample of 40 purchase orders from a population of 800 and finds $6,000 in duplicate payment errors. When the auditor extrapolates the $6,000 across the full population, the resulting $120,000 projected amount is classified as:', '["A factual misstatement because the $6,000 was directly observed in testing", "A judgmental misstatement because it reflects the auditor''s professional estimation", "A likely misstatement representing the auditor''s best estimate of the total population error", "A clearly trivial amount because the actual detected error was only $6,000"]'::jsonb, 2, 'AU-C 530.13 requires the auditor to project misstatements found in a sample to the population. The resulting projected amount is a likely (projected) misstatement — the auditor''s best estimate of the population error. The $6,000 actually observed is the known (factual) misstatement. Unlike factual misstatements, projected misstatements involve estimation and are accumulated separately on the summary of uncorrected misstatements.', 'medium', 2),

-- Q19: easy / L1 — Purpose of the summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the auditor''s summary of uncorrected misstatements under AU-C 450?', '["To document all accumulated misstatements for evaluating their aggregate effect on the financial statements", "To serve as a formal report delivered to regulatory agencies overseeing the entity", "To list only those misstatements that individually exceed the materiality threshold", "To replace the management representation letter regarding financial statement accuracy"]'::jsonb, 0, 'AU-C 450.05-.06 requires the auditor to accumulate misstatements on a summary so their aggregate effect on the financial statements can be evaluated. The summary enables the auditor to determine whether uncorrected misstatements, individually or combined, are material. It is not a regulatory filing and does not replace the management representation letter — rather, it is attached to that letter.', 'easy', 1),

-- Q20: easy / L1 — Magnitude component in deficiency severity assessment
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what does ''magnitude'' refer to when assessing the severity of a control deficiency?', '["The number of transactions processed by the deficient control during the period", "The frequency with which the control deficiency occurs during the audit period", "The length of time the control deficiency has existed without remediation", "The potential dollar amount of misstatement that could result from the control deficiency"]'::jsonb, 3, 'Under AU-C 265.A8, severity is evaluated based on the magnitude of the potential misstatement resulting from the deficiency and the likelihood of occurrence. Magnitude refers to the financial amount that could be misstated, not the number of transactions or duration. Likelihood is the separate probability component. A deficiency affecting a high-dollar account has greater magnitude than one affecting a smaller account.', 'easy', 1),

-- Q21: medium / L3 — Directional pattern of misstatements suggesting management bias
(1, 'Misstatements and Control Deficiencies', 'While evaluating uncorrected misstatements at Northgate Properties, the auditor observes that all seven misstatements increase reported net income, collectively adding $85,000 against materiality of $200,000. Under AU-C 450, the auditor should:', '["Accept the misstatements because their aggregate does not exceed materiality", "Consider whether the directional pattern indicates possible management bias in preparing the financial statements", "Issue a disclaimer of opinion due to the systematic income-increasing nature of the misstatements", "Reclassify all seven misstatements as fraudulent and withdraw from the engagement"]'::jsonb, 1, 'AU-C 450.11(b) requires the auditor to consider whether uncorrected misstatements indicate a possible bias in management''s judgments about accounting estimates. A consistent income-increasing direction across all misstatements is a qualitative indicator of potential bias. The auditor should not automatically conclude fraud, but the pattern requires professional skepticism and may affect the overall assessment of the financial statements.', 'medium', 3),

-- Q22: easy / L1 — Definition of deficiency in design
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what defines a deficiency in the design of an internal control?', '["A properly designed control that employees fail to execute consistently", "A control that operates as designed but produces errors exceeding materiality", "A control that is missing or not suitably designed to prevent or detect misstatements on a timely basis", "A control that was effective in prior years but has since become obsolete"]'::jsonb, 2, 'AU-C 265.A1 defines a design deficiency as existing when a control necessary to meet a control objective is missing, or when an existing control is not suitably designed so that even if it operated as designed, the objective would not be met. This differs from an operating deficiency, where a properly designed control fails in execution due to human error or circumvention.', 'easy', 1),

-- Q23: hard / L4 — Assessing remediation of a previously reported material weakness
(1, 'Misstatements and Control Deficiencies', 'Sunrise Manufacturing reported a material weakness in inventory valuation controls last year. Management implemented new cycle count procedures and hired an inventory manager in March 2026. The auditor tests the new controls and finds they operated effectively for nine months. Under AU-C 265, the auditor should:', '["Report the material weakness as fully remediated because the new controls operated effectively for the majority of the year", "Evaluate whether the controls operated for a sufficient period and assess the risk exposure during the unremediated months before concluding", "Automatically downgrade the classification to significant deficiency because partial-year operation prevents full remediation", "Defer the remediation assessment to the following year when a full twelve months of operating effectiveness can be evaluated"]'::jsonb, 1, 'Under AU-C 265.A14, the auditor evaluates whether a previously reported material weakness has been remediated by assessing whether new or modified controls operated effectively for a sufficient period. The auditor must also consider risk exposure during the unremediated period. Nine months does not automatically confirm or preclude remediation — the auditor exercises professional judgment about sufficiency of the operating period and interim risk.', 'hard', 4),

-- Q24: hard / L4 — Aggregate misstatements approaching materiality with undetected error risk
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Enterprises has $185,000 in accumulated uncorrected misstatements from prior and current periods spanning five accounts. Materiality is $200,000. Management refuses to correct them. The auditor determines the aggregate approaches materiality. Under AU-C 450, the most critical evaluation step is to:', '["Accept the financial statements because the aggregate technically remains below the materiality threshold", "Issue an adverse opinion because the misstatements span multiple accounts and fiscal periods", "Evaluate whether the misstatements, combined with further possible undetected misstatements, could exceed materiality", "Reduce materiality to $185,000 so the accumulated misstatements automatically become material"]'::jsonb, 2, 'AU-C 450.11 requires the auditor to determine whether uncorrected misstatements are material individually or in aggregate. When aggregates approach materiality, AU-C 450.A22 directs the auditor to consider the risk that further undetected misstatements exist. Simply comparing the total to the threshold ignores estimation uncertainty. Reducing materiality to force a result or accepting based on a narrow margin both fail to apply professional judgment appropriately.', 'hard', 4),

-- Q25: medium / L3 — Dual-purpose testing and control deficiency identification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bayshore Logistics, the auditor performs dual-purpose testing of purchase order approvals. The sample reveals that 8 of 30 tested approvals were performed by unauthorized personnel, though no monetary misstatements resulted. Under AU-C 265, the auditor should:', '["Conclude there is no deficiency because no financial misstatements were detected in the sample", "Report the finding as a lesser operating deficiency to management only, not to governance", "Perform additional substantive procedures only and defer deficiency evaluation until year-end", "Evaluate the control failure rate to determine whether a significant deficiency or material weakness exists"]'::jsonb, 3, 'AU-C 265.08 requires the auditor to evaluate identified control deficiencies to determine their severity, regardless of whether actual misstatements resulted. An 8-of-30 failure rate (27%) in authorization controls indicates the control is not operating effectively. The absence of monetary misstatements does not eliminate the deficiency — severity depends on the magnitude of potential misstatements and the likelihood the deficiency could result in material misstatement.', 'medium', 3),

-- Q26: medium / L3 — Aggregation of individually minor deficiencies
(1, 'Misstatements and Control Deficiencies', 'The auditor of Crestfield Energy identifies three control deficiencies: (1) occasional late bank reconciliation reviews, (2) inconsistent documentation of cash receipt approvals, and (3) unrestricted user access to the cash receipts journal. Individually, none qualifies as a significant deficiency. Under AU-C 265, the auditor should:', '["Report each deficiency separately to management without further combined evaluation", "Assess whether the combination of deficiencies affecting the same cash process together constitutes a significant deficiency", "Classify all three as material weaknesses because they share a common business process", "Disregard the deficiencies because individually they do not meet the significant deficiency threshold"]'::jsonb, 1, 'AU-C 265.A13 requires the auditor to consider whether a combination of control deficiencies affecting the same significant account, assertion, or process may collectively constitute a significant deficiency or material weakness. Three deficiencies all affecting the cash cycle create combined risk greater than any single one alone. Evaluating each in isolation without considering aggregate effect would understate overall control risk.', 'medium', 3),

-- Q27: easy / L2 — Simple scenario identifying severity level
(1, 'Misstatements and Control Deficiencies', 'During the audit of Maple Grove Bakery, the auditor discovers that the bookkeeper occasionally fails to record small cash register overages averaging $15 per week. Annual materiality is $50,000. This control failure is most likely classified as:', '["A material weakness because any control failure involving cash handling requires escalation", "A significant deficiency because cash-handling control failures are automatically elevated", "A lesser deficiency that does not rise to a significant deficiency or material weakness", "Not a control deficiency because the dollar amounts are too small to warrant consideration"]'::jsonb, 2, 'Under AU-C 265.A8, severity depends on the magnitude of potential misstatement and the likelihood that the deficiency could result in material misstatement. Weekly $15 overages against $50,000 materiality represent low magnitude and low likelihood. It is still a control deficiency because the control is not operating effectively, but it does not meet the threshold for significant deficiency, which requires reasonable possibility of more-than-inconsequential misstatement.', 'easy', 2),

-- Q28: easy / L1 — Definition of an operating deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is a deficiency in the operation of an internal control?', '["A control that is missing from the entity''s system of internal control entirely", "A control that was never formally documented in the entity''s written policies", "A control that is not suitably designed to achieve its stated control objective", "A properly designed control that does not operate effectively or is performed by someone lacking authority"]'::jsonb, 3, 'AU-C 265.A2 defines an operating deficiency as existing when a properly designed control does not operate effectively, or when the person performing the control lacks the necessary authority or competence. The control''s design is adequate, but execution fails. This contrasts with a design deficiency, where the control itself is missing or improperly structured, meaning it would fail even if perfectly performed.', 'easy', 1),

-- Q29: medium / L3 — Root cause analysis elevating deficiency classification
(1, 'Misstatements and Control Deficiencies', 'Horizon Pharmaceuticals'' quality assurance manager failed to review three consecutive monthly inventory reconciliations. Investigation reveals the manager was reassigned to another department with no replacement reviewer designated. Under AU-C 265, the root cause most likely affects severity classification because:', '["Three consecutive missed reviews automatically constitutes a material weakness under the standard", "The deficiency is mitigated because the manager still works for the company in another capacity", "A systemic staffing gap indicates the failure is likely to recur rather than being an isolated incident", "The auditor must defer classification until the next audit confirms whether the gap continues"]'::jsonb, 2, 'AU-C 265.A11 indicates the auditor should consider the cause of the deficiency when evaluating severity. A root cause reflecting a systemic issue — such as reassignment without replacement — elevates severity because the deficiency is expected to persist. An isolated oversight by an otherwise-functioning reviewer would be less severe. Root cause analysis distinguishes between temporary lapses and structural control failures.', 'medium', 3),

-- Q30: medium / L2 — Re-communication of previously reported deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Sterling Enterprises, the auditor communicated a significant deficiency in the revenue recognition process. The current-year audit reveals the same deficiency remains unremediated. Under AU-C 265, the auditor''s obligation is to:', '["Reference the prior-year communication without issuing a new written communication", "Orally inform governance that the previously reported deficiency persists", "Downgrade the classification to a lesser deficiency because governance is already aware of the issue", "Communicate the significant deficiency again in writing for the current year"]'::jsonb, 3, 'AU-C 265.A17 states that if a significant deficiency or material weakness communicated in a prior audit has not been remediated, the auditor should communicate it again in the current year''s written communication. Prior-year communications alone are insufficient because governance personnel may have changed and the current audit must independently document deficiencies. Oral notification does not satisfy AU-C 265 requirements.', 'medium', 2)
;

COMMIT;
